<script setup>import{ref}from'vue';const nome=ref('Nicolas');const cliques=ref(0)</script><template><main><div class="badge">Vue 3</div><h1>Projeto Vue</h1><p>Olá, <strong>{{nome}}</strong>! Este exemplo usa estado reativo com Composition API.</p><div class="panel"><span>Interações realizadas</span><strong>{{cliques}}</strong></div><button @click="cliques++">Adicionar interação</button></main></template><style>*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:radial-gradient(circle at top,#14532d 0,#0b1f19 38%,#07110d 100%);color:#f0fdf4}main{width:min(600px,100%);padding:38px;border-radius:26px;background:linear-gradient(180deg,rgba(12,35,27,.96),rgba(7,22,17,.97));border:1px solid rgba(74,222,128,.18);box-shadow:0 26px 80px rgba(0,0,0,.42)}.badge{display:inline-flex;padding:7px 11px;border-radius:999px;background:rgba(34,197,94,.14);border:1px solid rgba(74,222,128,.25);color:#86efac;font-size:.78rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase}h1{margin:18px 0 10px;font-size:clamp(2.2rem,6vw,3.5rem);letter-spacing:-.05em}p{margin:0;color:#a7c7b4;line-height:1.65}.panel{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:30px 0 20px;padding:18px 20px;border-radius:18px;background:#071a13;border:1px solid #1f4937}.panel span{color:#9cc4ac}.panel strong{font-size:2.3rem;color:#86efac}button{width:100%;border:0;border-radius:14px;padding:14px 18px;background:linear-gradient(135deg,#22c55e,#059669);color:white;font-weight:800;font-size:1rem;cursor:pointer;transition:.2s}button:hover{transform:translateY(-2px);filter:brightness(1.08)}@media(max-width:520px){main{padding:26px}.panel{align-items:flex-start;flex-direction:column}}</style>